  const seeded = [...field].sort((a, b) => strength[b] - strength[a]);
  const pots = [];
  for (let p = 0; p < 4; p++) pots.push(shuffle(seeded.slice(p * fmt.groups, (p + 1) * fmt.groups)));
  const groups = [];
