    year,
    name: fmt.name,
    short: fmt.short,
    kind: fmt.kind,
    confederation: fmt.confederation,
    nation,
    teams: fmt.teams,
    qualifying,
    qualified,
    squad,
    groupTable,
    bracket,
    champion,
    runnerUp,
    groupLabel: myGroupIdx >= 0 ? `Group ${String.fromCharCode(65 + myGroupIdx)}` : void 0,
    thirdsThrough: fmt.thirdsThrough,
