function leagueOf(clubName) {
  const real = REAL_LEAGUES.find((l) => effectiveClubsOf(l.id, l.clubs).includes(clubName));
  if (real) return effectiveLeague(real);
  for (const eraId of ERA_FALLBACK_ORDER) {
    const hit = (ERA_LEAGUES[eraId] ?? []).find((l) => l.clubs.includes(clubName));
    if (hit) return hit;
  }
  return Object.values(ERA_LEAGUES).flat().find((l) => l.clubs.includes(clubName)) ?? effectiveLeague(REAL_LEAGUES[0]);
}
